const SHORTCUT_NAMED_KEYS = new Set(["enter", "escape", "delete", "left", "right", "up", "down", "f1", "f2", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12", "comma", "period", "slash", "backslash", "minus", "equal", "leftbracket", "rightbracket"]);

/** Canonicalize a shortcut spelling to the wire form: lowercase '+'-joined
 * tokens, modifiers ordered primary, shift, alt, then one key (a-z, 0-9,
 * or the closed named set). Rejects whitespace, empty tokens, repeated
 * modifiers, aliases (ctrl/cmd/option), and unknown or multiple or missing
 * keys. POLICY stays at the core, validated on the canonical spelling. */
export function canonicalize_shortcut(spelling: string): string {
  if (!spelling) throw new Error("kaya: shortcut is empty");
  if (/[ \t\n\v\f\r]/.test(spelling)) throw new Error(`kaya: shortcut ${JSON.stringify(spelling)} contains whitespace`);
  const parts = spelling.toLowerCase().split("+");
  if (parts.some((p) => !p)) throw new Error(`kaya: shortcut ${JSON.stringify(spelling)} has an empty token`);
  const mods = parts.slice(0, -1);
  const key = parts[parts.length - 1]!;
  const seen: string[] = [];
  for (const m of mods) {
    if (m !== "primary" && m !== "shift" && m !== "alt") {
      throw new Error(`kaya: shortcut ${JSON.stringify(spelling)} has an unknown modifier ${JSON.stringify(m)} (the portable modifiers are primary, shift, alt; aliases like ctrl, cmd, and option are not accepted)`);
    }
    if (seen.includes(m)) throw new Error(`kaya: shortcut ${JSON.stringify(spelling)} repeats modifier ${JSON.stringify(m)}`);
    seen.push(m);
  }
  const alnum = key.length === 1 && /^[a-z0-9]$/.test(key);
  if (!alnum && !SHORTCUT_NAMED_KEYS.has(key)) {
    throw new Error(`kaya: shortcut ${JSON.stringify(spelling)} key ${JSON.stringify(key)} is outside the floor (one of a-z, 0-9, or the closed named set)`);
  }
  return [...["primary", "shift", "alt"].filter((m) => seen.includes(m)), key].join("+");
}

